        &&& ret matches Some(ret) ==> {
            &&& self.cell_id == pre.cell_id
            &&& self.batch_perms matches Some(batch_perms)
            &&& batch_perms.mem_contents().is_uninit()
            &&& batch_perms@.pcell == self.cell_id
